$source = DecisionQueueController::GetVariable("NuminousSpellSource");
$targets = FilterSpellshroudTargets(array_merge(ZoneSearch("myField", ["ALLY", "CHAMPION"]), ZoneSearch("theirField", ["ALLY", "CHAMPION"])));
if(!empty($targets)) {
$choices = implode("&", $targets);
$target = await $player.MZChoose($choices, "Choose_a_unit_for_the_granted_Spell");
