$targets = GAOrbTargets();
if(!empty($targets)) {
    $choices = implode("&", $targets);
    $first = await $player.MZMayChoose($choices, "Choose_the_first_card_to_seal_or_pass");
    if(in_array($first, ["", "-", "PASS"], true)) return;
    $zone = explode("-", $first)[0];
    $others = array_values(array_diff(GAOrbTargets($zone), [$first]));
    $selection = $first;
    if(!empty($others)) {
        $choices = implode("&", $others);
        $second = await $player.MZMayChoose($choices, "Choose_a_second_card_in_the_same_banishment_or_pass");
        if(!in_array($second, ["", "-", "PASS"], true)) $selection .= "&" . $second;
    }
    GAOrbSeal($player, $selection);
}

