$targets = GASoulMaterialChoices($player);
if(!empty($targets)) {
    $choices = implode("&", $targets);
    $chosen = await $player.MZMayChoose($choices, "Look_at_the_opponents_material_deck_and_choose_a_regalia_or_pass");
